#!/usr/bin/env python3
"""PS-4 flat wall panels.

Model (PS-4 2.1-2.5, 3, 4): rectangular plate a x b x t, all four edges clamped and
held against in-plane movement, uniform pressure, thin-plate (Kirchhoff) theory with
von Karman large-deflection (membrane) terms, linear elastic isotropic material.

In dimensionless form (W = w/t, S = sigma b^2 (1-nu^2) / (E t^2), Q = p b^4 / (E t^4))
the results depend on r = a/b, nu and Q only.  They are obtained by a Ritz method
(Legendre polynomial bases satisfying the clamped/immovable edge conditions, Newton
iteration).  A table of W/Q and S/Q over r in [1,3], nu in [0.22,0.42] and
Q in [1e-3, 2e4], computed with this same solver (12 x 12 terms per field), is embedded
below and interpolated (cubic); outside the table the solver is run directly.

Usage: python3 panels.py PACKAGE_DIR OUT_CSV
"""
import numpy as np
from numpy.polynomial import legendre as L

def basis1d(kind, K, pts):
    # returns list of (f, f', f'') arrays shape (npts, K)
    out = []
    for i in range(K):
        if kind == 'W':   # even, clamped
            p = np.polynomial.Legendre.basis(2 * i) * np.polynomial.Polynomial([1, 0, -1]).convert(kind=np.polynomial.Legendre)**2
        elif kind == 'E':
            p = np.polynomial.Legendre.basis(2 * i) * np.polynomial.Polynomial([1, 0, -1]).convert(kind=np.polynomial.Legendre)
        else:
            p = np.polynomial.Legendre.basis(2 * i + 1) * np.polynomial.Polynomial([1, 0, -1]).convert(kind=np.polynomial.Legendre)
        out.append((p(pts), p.deriv(1)(pts), p.deriv(2)(pts)))
    return [np.array([o[d] for o in out]).T for d in range(3)]

class Ritz:
    def __init__(self, r, nu, Kx, Ky, mx=None, my=None):
        self.nu = nu
        mx = mx or 2 * Kx + 6; my = my or 2 * Ky + 6
        gx, wx = L.leggauss(2 * mx); gx, wx = gx[mx:], 2 * wx[mx:]
        gy, wy = L.leggauss(2 * my); gy, wy = gy[my:], 2 * wy[my:]
        sx, sy = 2.0 / r, 2.0
        self.wq = np.kron(wx, wy)
        B = {}
        for k in 'WEO':
            B['x', k] = basis1d(k, Kx, gx); B['y', k] = basis1d(k, Ky, gy)
        def T(kx, ky, dx, dy):
            return np.kron(B['x', kx][dx], B['y', ky][dy]) * (sx**dx) * (sy**dy)
        self.U = {d: T('O', 'E', *d) for d in [(1, 0), (0, 1)]}
        self.V = {d: T('E', 'O', *d) for d in [(1, 0), (0, 1)]}
        self.W = {d: T('W', 'W', *d) for d in [(0, 0), (1, 0), (0, 1), (2, 0), (0, 2), (1, 1)]}
        n = Kx * Ky; self.n = n
        # edge point eta=1, xi=0 ; centre
        e0x = basis1d('W', Kx, np.array([0.0])); e1y = basis1d('W', Ky, np.array([1.0]))
        self.wc = np.kron(e0x[0], basis1d('W', Ky, np.array([0.0]))[0])[0]
        self.wyy = np.kron(e0x[0], e1y[2])[0] * sy**2
        self.vy = np.kron(basis1d('E', Kx, np.array([0.0]))[0], basis1d('O', Ky, np.array([1.0]))[1])[0] * sy
        self.fW = self.W[0, 0].T @ self.wq
        # linear stiffness
        z = np.zeros(3 * n); self.x = z
        self.H0 = self.hess(z)[1]

    def hess(self, x, q=0.0):
        n, nu = self.n, self.nu; c1 = (1 - nu) / 2
        u, v, w = x[:n], x[n:2 * n], x[2 * n:]
        q_ = self.wq
        Gx = self.W[1, 0]; Gy = self.W[0, 1]
        Wx, Wy = Gx @ w, Gy @ w
        Ux, Uy, Vx, Vy = self.U[1, 0], self.U[0, 1], self.V[1, 0], self.V[0, 1]
        ex = Ux @ u + Wx**2 / 2; ey = Vy @ v + Wy**2 / 2
        g = Uy @ u + Vx @ v + Wx * Wy
        Nx = q_ * (ex + nu * ey); Ny = q_ * (ey + nu * ex); Nxy = q_ * c1 * g
        if not hasattr(self, 'K0'):
            self.build_const()
        grad = np.empty(3 * n)
        grad[:n] = Ux.T @ Nx + Uy.T @ Nxy
        grad[n:2 * n] = Vy.T @ Ny + Vx.T @ Nxy
        grad[2 * n:] = Gx.T @ (Wx * Nx + Wy * Nxy) + Gy.T @ (Wy * Ny + Wx * Nxy) + self.Kb @ w - q * self.fW
        H = self.K0.copy()
        A = Wx[:, None] * Gx; B = Wy[:, None] * Gy; Cg = Wx[:, None] * Gy + Wy[:, None] * Gx
        qA = q_[:, None] * A; qB = q_[:, None] * B; qC = (c1 * q_)[:, None] * Cg
        sx = qA + nu * qB; sy = nu * qA + qB
        HUW = Ux.T @ sx + Uy.T @ qC
        HVW = Vy.T @ sy + Vx.T @ qC
        HWW = A.T @ sx + B.T @ sy + Cg.T @ qC
        T = Gx.T @ (Nx[:, None] * Gx + Nxy[:, None] * Gy)
        HWW += T + (Gy.T @ (Ny[:, None] * Gy + Nxy[:, None] * Gx))
        H[:n, 2 * n:] += HUW; H[2 * n:, :n] += HUW.T
        H[n:2 * n, 2 * n:] += HVW; H[2 * n:, n:2 * n] += HVW.T
        H[2 * n:, 2 * n:] += HWW
        return grad, H

    def build_const(self):
        n, nu = self.n, self.nu; c1 = (1 - nu) / 2; q_ = self.wq[:, None]
        Ux, Uy, Vx, Vy = self.U[1, 0], self.U[0, 1], self.V[1, 0], self.V[0, 1]
        K0 = np.zeros((3 * n, 3 * n))
        K0[:n, :n] = Ux.T @ (q_ * Ux) + c1 * Uy.T @ (q_ * Uy)
        K0[n:2*n, n:2*n] = Vy.T @ (q_ * Vy) + c1 * Vx.T @ (q_ * Vx)
        K0[:n, n:2*n] = nu * Ux.T @ (q_ * Vy) + c1 * Uy.T @ (q_ * Vx)
        K0[n:2*n, :n] = K0[:n, n:2*n].T
        A = self.W[2, 0] * q_; Bq = self.W[0, 2] * q_; Cq = self.W[1, 1] * q_
        self.Kb = (self.W[2, 0].T @ (A + nu * Bq) + self.W[0, 2].T @ (Bq + nu * A) + 2 * (1 - nu) * self.W[1, 1].T @ Cq) / 12
        K0[2*n:, 2*n:] = self.Kb
        self.K0 = K0

    def solve(self, q):
        x = self.x.copy()
        if np.max(np.abs(x)) == 0:
            x = np.linalg.solve(self.H0, np.r_[np.zeros(2 * self.n), q * self.fW])
        for it in range(50):
            g, H = self.hess(x, q)
            dx = np.linalg.solve(H, -g)
            x += dx
            if np.max(np.abs(dx)) < 1e-10 * np.max(np.abs(x)): break
        self.x = x
        n = self.n
        return self.wc @ x[2 * n:], self.vy @ x[n:2 * n] + abs(self.wyy @ x[2 * n:]) / 2

